    for (int i = 0; i < n; ++i) {
        cin >> a[i];
    }

    vector<vector<int>> dp(n + 1, vector<int>(k + 1, 0));
    dp[0][0] = 1;

    for (int i = 1; i <= n; ++i) {
        for (int j = 0; j <= k; ++j) {
            for (int l = 0; l <= min(j, a[i - 1]); ++l) {
                dp[i][j] = add(dp[i][j], dp[i - 1][j - l]);
            }
        }
    }

    cout << dp[n][k] << endl;

