#include <bits/stdc++.h>
using namespace std;

const int MOD = 1e9 + 7;

int N;
vector<vector<int>> G;
vector<int> sz;
vector<int> dp;

void dfs(int v, int p) {
    sz[v] = 1;
    for (int u : G[v]) {
        if (u == p) continue;
        dfs(u, v);
        sz[v] += sz[u];
    }
    dp[v] = 1;
    for (int u : G[v]) {
        if (u == p) continue;
        dp[v] = (1LL * dp[v] * dp[u]) % MOD;
    }
    if (sz[v] % 2 == 0) {
        dp[v] = (dp[v] * 2) % MOD;
    }
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(nullptr);

    cin >> N;
    G.resize(N);
    sz.resize(N);
    dp.resize(N);
    for (int i = 0; i < N - 1; i++) {
        int a, b;
        cin >> a >> b;
        a--, b--;
        G[a].push_back(b);
        G[b].push_back(a);
    }
    dfs(0, -1);
    cout << dp[0] << '\n';

    return 0;
}

#include <iostream>
#include <vector>

using namespace std;

void solve() {
    int n, k;
    cin >> n >> k;

    vector<long long> dp(k);
    for (int i = 0; i < k; i++) {
        dp[i] = 1;
    }

    for (int i = 1; i < n; i++) {
        vector<long long> next(k, 0);
        long long sum = 0;
        for (int j = 0; j < k; j++) {
            sum += dp[j];
        }
        for (int j = 0; j < k; j++) {
            next[j] = sum - dp[j];
        }
        dp = next;
    }

    long long ans = 0;
    for (int i = 0; i < k; i++) {
        ans += dp[i];
    }
    cout << ans << endl;
}

int main() {
    solve();
    return 0;
}

