            continue;
        }

        bool counter_clockwise = true;
        cur = 1;
        for (int i = n - 1; i >= 0; --i) {
            if (p[i] != cur) {
                counter_clockwise = false;
                break;
            }
            cur = p[(i + 1) % n];
            if (cur == n) cur = 1;
        }

        if (counter_clockwise) {
            cout << "YES\n";
            continue;
        }

        cout << "NO\n";
    }
    return 0;
}

