    dp[0] = 0;
    for (int i = 1; i <= sum; i++) {
        long long p = i * inv(sum) % mod;
        long long q = (sum - i) * inv(sum) % mod;
        long long r = (n - 1) * inv(n) % mod;
        dp[i] = (p * (dp[i - 1] + 1) % mod + (q * r % mod * (dp[i - 1] + 1) % mod + q * (1 - r) % mod * (dp[i] + 1) % mod)) % mod;
        dp[i] = dp[i] * inv((1 - q * (1 - r) % mod + mod) % mod) % mod;
    }
    cout << dp[sum] << endl;
    return 0;
}

