vector<vector<int>> d = {{-1, 0}, {1, 0}, {0, -1}, {0, 1}};

int r, c, n;
vector<pair<int, int>> queries;
vector<vector<bool>> marked;

bool valid(int x, int y) {
    return x >= 0 && x < r && y >= 0 && y < c;
}

bool bfs() {
    vector<vector<bool>> visited(r, vector<bool>(c, false));
    queue<pair<int, int>> q;
    for (int i = 0; i < c; i++) {
        if (!marked[0][i]) {
            q.push({0, i});
            visited[0][i] = true;
        }
    }
    while (!q.empty()) {
        auto [x, y] = q.front();
        q.pop();
        for (auto &[dx, dy] : d) {
            int nx = x + dx, ny = y + dy;
            if (nx == r) return true;
            if (nx < 0 || !valid(nx, ny) || marked[nx][ny] || visited[nx][ny]) continue;
            if (nx == x && (y == 0 || y == c - 1)) {
                if (ny == 0 || ny == c - 1) {
                    q.push({nx, ny});
                    visited[nx][ny] = true;
                }
            } else {
                q.push({nx, ny});
                visited[nx][ny] = true;
            }
        }
    }
    return false;
}

