    vector<vector<int>> farthest(n + 1);

    for (int i = 0; i < m; i++) {
        int ma = 0;
        for (int j = 1; j <= n; j++) {
            if (dist[mon[i]][j] > ma) {
                ma = dist[mon[i]][j];
                farthest[mon[i]].clear();
                farthest[mon[i]].push_back(j);
            } else if (dist[mon[i]][j] == ma) {
                farthest[mon[i]].push_back(j);
            }
        }
        max_dist[mon[i]] = ma;
    }

    int ans1 = 0, ans2 = 0;
    for (int i = 1; i <= n; i++) {
        if (find(mon.begin(), mon.end(), i) == mon.end()) {
            set<int> s;
            for (int j = 0; j < m; j++) {
                for (int k = 0; k < farthest[mon[j]].size(); k++) {
                    if (dist[mon[j]][i] + dist[i][farthest[mon[j]][k]] == max_dist[mon[j]]) {
                        s.insert(mon[j]);
                    }
                }
            }
            if (s.size() > ans1) {
                ans1 = s.size();
                ans2 = 1;
            } else if (s.size() == ans1) {
                ans2++;
            }
        }
    }

    cout << ans1 << ' ' << ans2 << '\n';

    return 0;
}

