        }
        ret = ret * 9 + c;
    }
    return ret;
}

int decode(int code, int p[9]) {
    int q[9];
    memset(q, 0, sizeof(q));
    for (int i = 8; i >= 1; i--) {
        p[i] = code % 9;
        code /= 9;
        for (int j = 1; j < i; j++) {
            if (p[j] > p[i]) q[p[j]]++;
        }
        p[i] += q[p[i]];
    }
    return 0;
}

