using namespace std;

double calcVolume(int a, int b, int c, int d, int e, int f) {
    double s = (double)(a + b + c) / 2.0;
    double S = sqrt(s * (s - a) * (s - b) * (s - c));
    double h = (2 * S) / a;

    double hh = (4 * S) / (a * b * c);
    return (1.0 / 12.0) * d * e * f * hh;
}

