using namespace std;

const double PI = acos(-1.0);

struct Point {
    double x, y;
};

double dist(const Point& p1, const Point& p2) {
    return sqrt((p1.x - p2.x) * (p1.x - p2.x) + (p1.y - p2.y) * (p1.y - p2.y));
}

double angle(const Point& p) {
    return atan2(p.y, p.x);
}

bool inside(const Point& p, double r, int m, int k) {
    double a = angle(p);
    if (a < 0) a += 2 * PI;
    int idx = int(a / (2 * PI / m));
    double d = dist(p, {0, 0});
    if (d > r) return false;
    if (k == 1) return true;
    double ang = (2 * PI / m) * (idx % k);
    if (a < ang || a >= ang + (2 * PI / m)) return false;
    return true;
}

int main() {
    int n, m, k;
    while (cin >> n >> m >> k) {
        if (n == 0 && m == 0 && k == 0) break;
        vector<Point> points(n);
        for (int i = 0; i < n; i++) {
            cin >> points[i].x >> points[i].y;
        }
        double lo = 0, hi = 1e9;
        for (int iter = 0; iter < 100; iter++) {
            double mid = (lo + hi) / 2;
            bool ok = true;
            for (int i = 0; i < n; i++) {
                if (!inside(points[i], mid, m, k)) {
                    ok = false;
                    break;
                }
            }
            if (ok) hi = mid;
            else lo = mid;
        }
        printf("%.10f\n", (lo + hi) / 2);
    }
    return 0;
}

#include <iostream>
#include <vector>
#include <string>
#include <algorithm>
#include <limits>
#include <queue>

using namespace std;

struct Edge {
    int to;
    int weight;
    int index;
};

struct Graph {
    int n;
    vector<vector<Edge>> adj;

    Graph(int n) : n(n), adj(n) {}

    void addEdge(int u, int v, int w, int index) {
        adj[u].push_back({v, w, index});
    }
};

struct MinCostFlow {
    Graph g;
    vector<int> pot;
    vector<int> dist;
    vector<int> par;

    MinCostFlow(int n) : g(n), pot(n), dist(n), par(n) {}

    bool spfa(int s, int t) {
        dist.assign(g.n, numeric_limits<int>::max());
        dist[s] = 0;

        vector<bool> inQueue(g.n, false);
        queue<int> q;
        q.push(s);
        inQueue[s] = true;

        while (!q.empty()) {
            int u = q.front();
            q.pop();
            inQueue[u] = false;

            for (const auto& e : g.adj[u]) {
                int v = e.to;
                int w = e.weight + pot[u] - pot[v];

                if (w < 0 && dist[u] + w < dist[v]) {
                    dist[v] = dist[u] + w;
                    par[v] = e.index;

                    if (!inQueue[v]) {
                        q.push(v);
                        inQueue[v] = true;
                    }
                }
            }
        }

        return dist[t]!= numeric_limits<int>::max();
    }

    void updatePot() {
        for (int i = 0; i < g.n; ++i) {
            pot[i] += dist[i];
        }
    }

    pair<int, long long> solve(int s, int t) {
        int flow = 0;
        long long cost = 0;

        while (spfa(s, t)) {
            updatePot();

            int minCap = numeric_limits<int>::max();
            for (int v = t; v!= s; v = g.adj[v][0].to) {
                for (const auto& e : g.adj[v]) {
                    if (e.index == par[v]) {
                        minCap = min(minCap, -e.weight);
                        break;
                    }
                }
            }

            flow += minCap;
            cost += minCap * pot[t];

            int v = t;
            while (v!= s) {
                int u = 0;
                for (const auto& e : g.adj[v]) {
                    if (e.index == par[v]) {
                        u = v;
                        break;
                    }
                }

                for (auto& e : g.adj[u]) {
                    if (e.to == v) {
                        e.weight += minCap;
                        break;
                    }
                }

                for (auto& e : g.adj[v]) {
                    if (e.to == u) {
                        e.weight -= minCap;
                        break;
                    }
                }

                v = u;
            }
        }

        return {flow, cost};
    }
};

int main() {
    int n, m;
    cin >> n >> m;

    vector<int> demands(n);
    vector<string> names(n);
    for (int i = 0; i < n; ++i) {
        cin >> names[i];
        demands[i] = 1;
    }

    int s = n;
    int t = n + 1;
    MinCostFlow g(n + 2);

    for (int i = 0; i < m; ++i) {
        int k;
        cin >> k;

        vector<int> cities(k);
        for (int j = 0; j < k; ++j) {
            string name;
            cin >> name;

            auto it = find(names.begin(), names.end(), name);
            cities[j] = it - names.begin();
        }

        int c1, c2;
        cin >> c1 >> c2;

        g.g.addEdge(s, cities[0], 0, -1);
        g.g.addEdge(cities[0], s, 0, -1);
        for (int j = 1; j < k; ++j) {
            g.g.addEdge(cities[j - 1], cities[j], c1, i);
            g.g.addEdge(cities[j], cities[j - 1], c2, i);
        }
        g.g.addEdge(cities[k - 1], t, 0, -1);
        g.g.addEdge(t, cities[k - 1], 0, -1);
    }

    auto result = g.solve(s, t);
    cout << result.second << " " << result.first << endl;

    return 0;
}

#include <bits/stdc++.h>
using namespace std;

const int MAX_N = 100;
const int MAX_M = 100;
const int MAX_W = 100;
const int MAX_H = 100;
const int MAX_STACK_SIZE = 50;
const int INF = 1e9;

int h, w;
char grid[MAX_N][MAX_M];
int dx[] = {1, 0};
int dy[] = {0, 1};
int dp[MAX_N][MAX_M][MAX_STACK_SIZE];

void reset_dp() {
    for (int i = 0; i < h; i++) {
        for (int j = 0; j < w; j++) {
            for (int k = 0; k < MAX_STACK_SIZE; k++) {
                dp[i][j][k] = -INF;
            }
        }
    }
}

int solve(int x, int y, int stack) {
    if (x >= h || y >= w) {
        return -INF;
    }
    if (x == h - 1 && y == w - 1) {
        return 0;
    }
    if (dp[x][y][stack]!= -INF) {
        return dp[x][y][stack];
    }
    int ans = -INF;
    for (int i = 0; i < 2; i++) {
        int nx = x + dx[i];
        int ny = y + dy[i];
        if (nx < h && ny < w && grid[nx][ny]!= '#') {
            if (grid[nx][ny] >= 'a' && grid[nx][ny] <= 'z') {
                if (stack == grid[nx][ny] - 'a') {
                    ans = max(ans, solve(nx, ny, stack) + 1);
                } else if (stack < MAX_STACK_SIZE - 1) {
                    ans = max(ans, solve(nx, ny, stack + 1));
                }
            } else if (grid[nx][ny] >= 'A' && grid[nx][ny] <= 'Z') {
                if (stack > 0 && stack - 1 == grid[nx][ny] - 'A') {
                    ans = max(ans, solve(nx, ny, stack - 1) + 1);
                } else {
                    ans = max(ans, solve(nx, ny, stack));
                }
            } else {
                ans = max(ans, solve(nx, ny, stack));
            }
        }
    }
    return dp[x][y][stack] = ans;
}

int main() {
    while (true) {
        cin >> h >> w;
        if (h == 0 && w == 0) {
            break;
        }
        for (int i = 0; i < h; i++) {
            for (int j = 0; j < w; j++) {
                cin >> grid[i][j];
            }
        }
        reset_dp();
        int ans = solve(0, 0, 0);
        if (ans == -INF) {
            cout << -1 << endl;
        } else {
            cout << ans << endl;
        }
    }
    return 0;
}

