                dp[i + 1][0] = (dp[i + 1][0] + 1LL * dp[k][0] * dp[i - k][1]) % MOD;
                dp[i + 1][1] = (dp[i + 1][1] + 1LL * dp[k][1] * dp[i - k][0]) % MOD;
            }

            dp[i + 1][0] = (dp[i + 1][0] + dp[j][0]) % MOD;
            dp[i + 1][1] = (dp[i + 1][1] + dp[j][1]) % MOD;
        }
    }

    cout << (dp[n][0] + dp[n][1]) % MOD << endl;

    return 0;
}

