class Matrix {
public:
    Matrix(int n) : n(n), data(n, vector<int>(n, 0)) {}

    void update(int x0, int y0, int x1, int y1, int v) {
        for (int i = x0 - 1; i < x1; i++) {
            for (int j = y0 - 1; j < y1; j++) {
                data[i][j] ^= v;
            }
        }
    }

    int query(int x0, int y0, int x1, int y1) {
        int result = 0;
        for (int i = x0 - 1; i < x1; i++) {
            for (int j = y0 - 1; j < y1; j++) {
                result ^= data[i][j];
            }
        }
        return result;
    }

private:
    int n;
    vector<vector<int>> data;
};

int main() {
