    for (int i = 0; i < m; i++) {
        int u, v;
        cin >> u >> v;
        u--, v--;
        adj[u].push_back(v);
        adj[v].push_back(u);
        railway[u][v] = railway[v][u] = true;
    }

    for (int i = 0; i < n; i++) {
        for (int j = 0; j < n; j++) {
            if (!railway[i][j] && i!= j) {
                adj[i].push_back(j);
                adj[j].push_back(i);
            }
        }
    }

