#include <set>
#include <cmath>

using namespace std;

struct Point {
    long long x, y;
    Point(long long x = 0, long long y = 0) : x(x), y(y) {}
};

long long cross(const Point &o, const Point &a, const Point &b) {
    return (a.x - o.x) * (b.y - o.y) - (b.x - o.x) * (a.y - o.y);
}

bool cmp(const Point &a, const Point &b) {
    return a.x == b.x? a.y < b.y : a.x < b.x;
}

vector<Point> convexHull(vector<Point> &points) {
    int n = points.size();
    if (n < 3) return {};
    sort(points.begin(), points.end(), cmp);
    vector<Point> up, down;
    for (int i = 0; i < n; i++) {
        while (up.size() >= 2 && cross(up[up.size() - 2], up.back(), points[i]) > 0)
            up.pop_back();
        up.push_back(points[i]);
    }
    for (int i = n - 1; i >= 0; i--) {
        while (down.size() >= 2 && cross(down[down.size() - 2], down.back(), points[i]) > 0)
            down.pop_back();
        down.push_back(points[i]);
    }
    up.pop_back();
    down.pop_back();
    up.insert(up.end(), down.begin(), down.end());
    return up;
}

int main() {
    int k, n;
    cin >> k >> n;
    vector<Point> points(k);
    for (int i = 0; i < k; i++) {
        cin >> points[i].x >> points[i].y;
    }
    vector<Point> monsters(n);
    for (int i = 0; i < n; i++) {
        cin >> monsters[i].x >> monsters[i].y;
    }
    set<int> afraid;
    for (int mask = 0; mask < (1 << k); mask++) {
        vector<Point> currPoints;
        for (int i = 0; i < k; i++) {
            if (mask & (1 << i)) {
                currPoints.push_back(points[i]);
            }
        }
        for (int i = 0; i < n; i++) {
            currPoints.push_back(monsters[i]);
        }
        vector<Point> hull = convexHull(currPoints);
        for (int i = 0; i < hull.size(); i++) {
            if (hull[i].x == monsters[i % n].x && hull[i].y == monsters[i % n].y) {
                afraid.insert(i % n);
            }
        }
    }
    cout << afraid.size() << endl;
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

const int N = 1e5 + 10, MOD = 1e9 + 7;

struct Node {
    long long val;
    int l, r, lazy;
};

Node tree[N << 2];
int arr[N], n, m;

void pushUp(int k) {
    tree[k].val = tree[k << 1].val + tree[k << 1 | 1].val;
}

void pushDown(int k) {
    if (tree[k].lazy) {
        tree[k << 1].val += (tree[k << 1].r - tree[k << 1].l + 1) * tree[k].lazy;
        tree[k << 1 | 1].val += (tree[k << 1 | 1].r - tree[k << 1 | 1].l + 1) * tree[k].lazy;
        tree[k << 1].lazy += tree[k].lazy;
        tree[k << 1 | 1].lazy += tree[k].lazy;
        tree[k].lazy = 0;
    }
}

void build(int k, int l, int r) {
    tree[k].l = l;
    tree[k].r = r;
    tree[k].lazy = 0;
    if (l == r) {
        tree[k].val = arr[l];
        return;
    }
    int mid = l + r >> 1;
    build(k << 1, l, mid);
    build(k << 1 | 1, mid + 1, r);
    pushUp(k);
}

void update(int k, int l, int r, int x) {
    if (l <= tree[k].l && tree[k].r <= r) {
        tree[k].val += (tree[k].r - tree[k].l + 1) * x;
        tree[k].lazy += x;
        return;
    }
    pushDown(k);
    int mid = tree[k].l + tree[k].r >> 1;
    if (l <= mid) {
        update(k << 1, l, r, x);
    }
    if (r > mid) {
        update(k << 1 | 1, l, r, x);
    }
    pushUp(k);
}

long long query(int k, int l, int r) {
    if (l <= tree[k].l && tree[k].r <= r) {
        return tree[k].val;
    }
    pushDown(k);
    int mid = tree[k].l + tree[k].r >> 1;
    long long res = 0;
    if (l <= mid) {
        res += query(k << 1, l, r);
    }
    if (r > mid) {
        res += query(k << 1 | 1, l, r);
    }
    return res;
}

long long fib(long long x) {
    if (x <= 1) {
        return 1;
    }
    long long a = 1, b = 1, c = 0;
    for (int i = 3; i <= x; i++) {
        c = (a + b) % MOD;
        a = b;
        b = c;
    }
    return c;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);
    cin >> n >> m;
    for (int i = 1; i <= n; i++) {
        cin >> arr[i];
    }
    build(1, 1, n);
    while (m--) {
        int op, l, r, x;
        cin >> op >> l >> r;
        if (op == 1) {
            cin >> x;
            update(1, l, r, x);
        } else {
            long long ans = 0;
            for (int i = l; i <= r; i++) {
                ans = (ans + fib(query(1, i, i))) % MOD;
            }
            cout << ans << "\n";
        }
    }
    return 0;
}

