const int MAX_N = 7007;

int next(int u, int v, int n) {
    return (u + v) % n;
}

int check(vector<int> &a, vector<int> &b, int u, int n) {
    vector<bool> used(MAX_N, false);
    used[u] = true;
    for (int k = 0; k < 2; k++) {
        int v = u;
        while (true) {
            bool found = false;
            for (int i = 0; i < a.size(); i++) {
                int t = next(v, a[i], n);
                if (!used[t]) {
                    used[t] = true;
                    v = t;
                    found = true;
                    break;
                }
            }
            if (!found) {
                break;
            }
        }
        swap(a, b);
    }
    if (used[0]) {
        return 1;
    } else if (used[u]) {
        return 0;
    } else {
        return 2;
    }
}

