vector<int> c[N];
bool vis[N];
int col[N];

int dfs(int u, int p) {
    vis[u] = true;
    col[u] = col[p] ^ 1;

    for (auto v : g[u]) {
        if (vis[v]) {
            if (col[u] == col[v]) {
                return -1;
            }
        } else {
            if (dfs(v, u) == -1) {
                return -1;
            }
        }
    }

    return 1;
}

