    }

    for (int i = 1; i <= m; ++i) {
        cin >> u[i] >> v[i];
        g[u[i]].push_back(v[i]);
        g[v[i]].push_back(u[i]);
        c[u[i]].push_back(i);
        c[v[i]].push_back(i);
    }

    col[1] = 0;
    int ok = dfs(1, 1);

    if (ok == -1) {
        cout << "-1\n";
        return 0;
    }

    int res = INF;
    for (int i = 1; i <= n; ++i) {
        if (col[i] == 0) {
            res = min(res, d[i]);
        }
    }

    for (int i = 1; i <= n; ++i) {
        if (col[i] == 0) {
            d[i] -= res;
        }
    }

