                    count++;
                }
            }

            if (count <= l) {
                right = mid;
            } else {
                left = mid + 1;
            }
        }

        if (left == N + 1) {
            std::cout << -1 << std::endl;
        } else {
            std::cout << left << std::endl;
        }
    }

