int val(char ch) {
    if (ch >= '0' && ch <= '9') return ch - '0';
    return ch - 'A' + 10;
}

int to_base10(string s, int base) {
    int num = 0, len = s.length(), p = 1;
    for (int i = len - 1; i >= 0; i--) {
        num += val(s[i]) * p;
        p *= base;
    }
    return num;
}

