    for (char ch : a + b) {
        min_base = max(min_base, val(ch) + 1);
    }
    vector<int> ans;
    for (int base = min_base; base <= 60; base++) {
        if (to_base10(a, base) < 24 && to_base10(b, base) < 60) {
            ans.push_back(base);
        }
    }
    if (ans.empty()) {
        cout << 0 << endl;
    } else if (ans.size() == 60 - min_base + 1) {
        cout << -1 << endl;
    } else {
        for (int base : ans) {
