            visited[i] = true;

            while (!q.empty()) {
                int curr = q.front();
                q.pop();

                for (int j = 0; j < graph.size(); j++) {
                    if (graph[curr][j] && subset[j] && !visited[j]) {
                        q.push(j);
                        visited[j] = true;
                    }
                }
            }
        }
    }

    for (int i = 0; i < graph.size(); i++) {
        if (subset[i] && !visited[i]) return false;
    }

    return true;
}

int countOnes(const vector<bool>& subset) {
    int count = 0;
    for (int i = 0; i < subset.size(); i++) {
        if (subset[i]) count++;
    }
    return count;
}

