int calculatePower(const string& actions) {
    int power = 0;
    for (char action : actions) {
        if (action == '<') {
            power--;
        } else if (action == '>') {
            power++;
        } else if (action == '(' || action == ')') {
            power += 2;
        } else if (action == '[' || action == ']') {
            power += 3;
        }
    }
    return power;
}

