    for (int i = 0; i < k * n; ++i) {
        cin >> cards[i];
    }

    vector<int> f(n);
    for (int i = 0; i < n; ++i) {
        cin >> f[i];
    }

    vector<int> h(k);
    for (int i = 0; i < k; ++i) {
        cin >> h[i];
    }

    vector<vector<int>> adjacency(n, vector<int>());
    for (int i = 0; i < k * n; ++i) {
        for (int j = 0; j < n; ++j) {
            if (cards[i] == f[j]) {
                adjacency[j].push_back(i);
            }
        }
    }

    vector<bool> visited(k * n, false);
    vector<int> dp(n, 0);
    for (int i = 0; i < n; ++i) {
