        });
        for (int j = 0; j < k && j < adjacency[i].size(); ++j) {
            if (!visited[adjacency[i][j]]) {
                visited[adjacency[i][j]] = true;
                dp[i]++;
            }
        }
    }

    int ans = 0;
    for (int i = 0; i < n; ++i) {
        ans += h[min(k - 1, dp[i])];
    }

