#include <iostream>
#include <vector>
#include <algorithm>

struct DisjointSetUnion {
    std::vector<int> parent;
    std::vector<int> rank;

    DisjointSetUnion(int n) : parent(n), rank(n, 0) {
        for (int i = 0; i < n; ++i)
            parent[i] = i;
    }

    int find(int x) {
        if (parent[x] != x)
            parent[x] = find(parent[x]);
        return parent[x];
    }

    void unionSet(int x, int y) {
        int rootX = find(x);
        int rootY = find(y);
        if (rootX == rootY)
            return;
        if (rank[rootX] < rank[rootY])
            parent[rootX] = rootY;
        else if (rank[rootX] > rank[rootY])
            parent[rootY] = rootX;
        else {
            parent[rootY] = rootX;
            rank[rootX]++;
        }
    }
};

struct Edge {
    int u, v;
    int cost;
};

bool compareEdges(const Edge& a, const Edge& b) {
    return a.cost < b.cost;
}

int main() {
    int N;
    std::cin >> N;
    std::vector<int> x(N), y(N);
    for (int i = 0; i < N; ++i)
        std::cin >> x[i] >> y[i];
    std::vector<Edge> edges;
    for (int i = 0; i < N; ++i)
        for (int j = i + 1; j < N; ++j) {
            int cost = std::min(std::abs(x[i] - x[j]), std::abs(y[i] - y[j]));
            edges.push_back({i, j, cost});
        }
    std::sort(edges.begin(), edges.end(), compareEdges);
    DisjointSetUnion dsu(N);
    int ans = 0;
    for (const auto& edge : edges) {
        if (dsu.find(edge.u) != dsu.find(edge.v)) {
            ans += edge.cost;
            dsu.unionSet(edge.u, edge.v);
        }
    }
    std::cout << ans << '\n';
    return 0;
}

#include <bits/stdc++.h>
using namespace std;

const int MAXN = 105;
const int INF = 1e9;

struct Edge {
    int u, v, w;
};

int n, m;
Edge edges[MAXN];
int dis[MAXN][MAXN];

void floyd() {
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= n; j++) {
            if (i == j) dis[i][j] = 0;
            else dis[i][j] = INF;
        }
    }
    for (int i = 0; i < m; i++) {
        dis[edges[i].u][edges[i].v] = edges[i].w;
        dis[edges[i].v][edges[i].u] = edges[i].w;
    }
    for (int k = 1; k <= n; k++) {
        for (int i = 1; i <= n; i++) {
            for (int j = 1; j <= n; j++) {
                dis[i][j] = min(dis[i][j], dis[i][k] + dis[k][j]);
            }
        }
    }
}

bool check(int id) {
    int u = edges[id].u, v = edges[id].v, w = edges[id].w;
    edges[id].w = INF;
    floyd();
    bool flag = false;
    for (int i = 1; i <= n; i++) {
        for (int j = 1; j <= n; j++) {
            if (dis[i][j] > dis[i][u] + w + dis[v][j] || dis[i][j] > dis[i][v] + w + dis[u][j]) {
                flag = true;
            }
        }
    }
    edges[id].w = w;
    return flag;
}

int main() {
    ios::sync_with_stdio(false);
    cin.tie(0);
    cin >> n >> m;
    for (int i = 0; i < m; i++) {
        cin >> edges[i].u >> edges[i].v >> edges[i].w;
    }
    floyd();
    int ans = 0;
    for (int i = 0; i < m; i++) {
        if (check(i)) ans++;
    }
    cout << ans << endl;
    return 0;
}

#include<bits/stdc++.h>
using namespace std;
#define MOD 1000000007
typedef long long ll;

int N, M, K;
int cnt = 0;
ll dp[310000][3], dp2[310000][3];
char c[310000];

void add(ll &x, ll y) {
    x = (x + y) % MOD;
}

void solve() {
    cin >> N >> M >> K;
    for (int i = 1; i <= N; ++i) {
        c[i] = 'a';
    }
    for (int i = N + 1; i <= N + M; ++i) {
        c[i] = 'b';
    }
    for (int i = N + M + 1; i <= N + M + K; ++i) {
        c[i] = 'c';
    }

    dp[0][1] = 1;
    dp[0][2] = 1;
    dp[0][0] = 1;

    int a, b, cc;
    for (a = 1; a <= N; ++a) {
        dp[a][1] = dp[a - 1][0];
    }
    for (b = 1; b <= M; ++b) {
        dp[N + b][2] = dp[N + b - 1][0];
    }
    for (cc = 1; cc <= K; ++cc) {
        dp[N + M + cc][0] = dp[N + M + cc - 1][0];
    }

    for (int i = 1; i <= N + M + K; ++i) {
        int x = c[i] - 'a';
        if (x == 0) {
            add(dp2[i][2], dp2[i - 1][1]);
            add(dp2[i][0], dp2[i - 1][0]);
            add(dp2[i][1], dp2[i - 1][2]);
        } else if (x == 1) {
            add(dp2[i][0], dp2[i - 1][0]);
            add(dp2[i][1], dp2[i - 1][1]);
            add(dp2[i][2], dp2[i - 1][2]);
        } else {
            add(dp2[i][1], dp2[i - 1][1]);
            add(dp2[i][2], dp2[i - 1][2]);
            add(dp2[i][0], dp2[i - 1][0]);
        }
        add(dp2[i][0], dp[i][0]);
        add(dp2[i][1], dp[i][1]);
        add(dp2[i][2], dp[i][2]);
    }

    cout << dp2[N + M + K][0];
}

int main() {
    ios_base::sync_with_stdio(false);
    cin.tie(NULL);

    int t = 1;
    //cin >> t;
    while (t--) {
        solve();
    }
}
